    <TooltipProvider compact tooltip={typeof tooltip !== 'undefined' ? tooltip : buttonProps.label}>
      <IconButton
        {...buttonProps}
        className={cx(cl['bk-banner__action'], cl['bk-banner__action--icon'], buttonProps.className)}
