// Map operators to a human-readable string to be shown in the UI

const numberOperatorsToSymbolMap: Record<FQ.NumberFieldOperator, string> = {
  '$eq': '\u003D',
  '$lt': '\u003C',
  '$lte': '\u2264',
  '$gt': '\u003E',
  '$gte': '\u2265',
  '$ne': '\u2260',
