export const ModalProvider = Object.assign(
  (props: ModalProviderProps) => {
    const {
      ref,
      children,
      dialog,
      activeDefault = false,
      allowUserClose = true,
      shouldCloseOnBackdropClick = true,
      unmountDelay = 3000, // ms
      renderMethod = 'portal',
    } = props;

